mapper.select:
SELECT o.type AS name, COUNT(*) AS count, COALESCE(SUM(o.amount), 0) AS amount
FROM tb_order o

    AND o.type = #{type}
    AND o.partner_id = #{partnerId}

GROUP BY o.type ORDER BY count DESC

SELECT p.name AS name, COUNT(*) AS count, COALESCE(SUM(o.amount), 0) AS amount
FROM tb_order o JOIN tb_partner p ON o.partner_id = p.id

    AND o.partner_id = #{partnerId}
    AND o.type = #{type}

GROUP BY p.name ORDER BY count DESC

SELECT o.status AS name, COUNT(*) AS count, COALESCE(SUM(o.amount), 0) AS amount
FROM tb_order o

    AND o.status = #{status}
    AND o.type = #{type}
    AND o.partner_id = #{partnerId}

GROUP BY o.status ORDER BY count DESC
